int Contar(int n)
{
    if (n <= 0) return 0;
    return n + Contar(n - 1);
}

int FactorialIterativo(int n)
{
    int r = 1;
    for (int i = 1; i <= n; i++)
        r *= i;
    return r;
}

int FactorialRecursivo(int n)
{
    if (n <= 1) return 1;
    return n * FactorialRecursivo(n - 1);
}

void CuentaRegresiva(int n) {
    if (n <= 0) {
        Console.WriteLine("¡Despegue!");
        return;
    }
    Console.WriteLine(n);
    CuentaRegresiva(n - 1);
}

int Factorial(int n)
{
    if (n <= 1) return 1;
    return n * Factorial(n - 1);
}

Console.WriteLine("--- Pruebas ---");
CuentaRegresiva(3);
int f = Factorial(4);
Console.WriteLine($"Factorial: {f}");

exercises.instruction:
